const {chromium}=require('playwright'),fs=require('fs'),os=require('os'),path=require('path'),http=require('http'),assert=require('assert/strict'),{execFileSync}=require('child_process');
const repo=path.resolve(__dirname,'../..'),dir=fs.mkdtempSync(path.join(os.tmpdir(),'sambaadm-search-'));
execFileSync('go',['test','./internal/web','-run','^TestWorkspaceBrowserFixtures$','-count=1'],{cwd:repo,env:{...process.env,SAMBAADM_WEB_FIXTURE_DIR:dir}});
const server=http.createServer((req,res)=>{const p=new URL(req.url,'http://localhost').pathname,file=p.startsWith('/static/')?path.join(repo,'internal/web',p):path.join(dir,'admin-'+p.slice(1)+'.html');if(!fs.existsSync(file)){res.writeHead(404).end();return;}res.setHeader('Content-Type',file.endsWith('.js')?'application/javascript':file.endsWith('.css')?'text/css':'text/html');res.end(fs.readFileSync(file));});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch({headless:true});try{const page=await browser.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.route('**/api/v1/**',route=>route.fulfill({json:route.request().url().includes('/directory/tree')?{kind:'domain',dn:'DC=example,DC=com',label:'example.com',children:[]}:[]}));await page.goto('http://127.0.0.1:'+server.address().port+'/users');await page.evaluate(()=>{const bar=document.createElement('div');bar.id='menu-fixture';bar.dataset.compactActions='1';for(const name of ['Основное действие','Дополнительное действие','Опасное действие']){const b=document.createElement('button');b.type='button';b.textContent=name;if(name.startsWith('Опасное'))b.className='danger';b.onclick=()=>window.lastAction=name;bar.append(b);}document.body.append(bar);});const bar=page.locator('#menu-fixture');await bar.locator('details').waitFor();assert.equal(await bar.getByRole('button',{name:'Основное действие',exact:true}).count(),1);assert.equal(await bar.getByRole('button',{name:'Дополнительное действие',exact:true}).count(),0);await bar.locator('summary').click();await bar.getByRole('button',{name:'Дополнительное действие',exact:true}).click();assert.equal(await page.evaluate(()=>window.lastAction),'Дополнительное действие');assert.equal(await bar.locator('details').evaluate(e=>e.open),false);await bar.locator('summary').focus();await page.keyboard.press('Enter');await bar.getByRole('button',{name:'Опасное действие',exact:true}).focus();await page.keyboard.press('Escape');assert.equal(await bar.locator('details').evaluate(e=>e.open),false);assert.equal(await bar.locator('summary').evaluate(e=>e===document.activeElement),true);
await page.evaluate(()=>{const form=document.createElement('form');form.id='form-fixture';form.dataset.compactActions='1';form.innerHTML='<input name="csrf_token" value="fixture" type="hidden"><button type="submit" name="action" value="save">Сохранить</button><button type="submit" name="action" value="download">Скачать сертификат</button>';form.onsubmit=event=>{event.preventDefault();window.submitted=Object.fromEntries(new FormData(form,event.submitter));};document.body.append(form);});const form=page.locator('#form-fixture');await form.locator('summary').click();await form.getByRole('button',{name:'Скачать сертификат',exact:true}).click();assert.deepEqual(await page.evaluate(()=>window.submitted),{csrf_token:'fixture',action:'download'});await page.evaluate(()=>{const b=document.createElement('button');b.textContent='Новая команда';b.type='button';document.querySelector('#menu-fixture').append(b);});await bar.locator('summary').click();await bar.getByRole('button',{name:'Новая команда',exact:true}).waitFor();assert.equal(await bar.locator('details').count(),1,'must not nest menus after dynamic updates');await page.setViewportSize({width:390,height:844});assert.equal(await bar.evaluate(e=>e.scrollWidth>e.clientWidth),false);for(const section of ['users','groups','computers','ou','domain','trusts','shares']){await page.unroute('**/api/v1/**');await page.route('**/api/v1/**',route=>{const path=new URL(route.request().url()).pathname;const json=path.includes('/directory/tree')?{kind:'domain',dn:'DC=example,DC=com',label:'example.com',children:[]}:path.endsWith('/domain/fsmo')?[{role:'PdcEmulationMaster',owner:'dc1.example.com'}]:[{samAccountName:'fixture',displayName:'Тестовый объект',name:'Тестовый объект',domain:'partner.example.com',dn:'CN=fixture,DC=example,DC=com',enabled:true}];return route.fulfill({json:path.endsWith('/users/fixture')?{...json[0],revision:'one',attributes:{}}:json});});await page.goto('http://127.0.0.1:'+server.address().port+'/'+section);await page.locator('tbody tr').first().waitFor();for(const cell of await page.locator('td.workspace-actions').all())assert(await cell.locator(':scope > button').count()<=1,'too many direct row commands in '+section);if(section==='users'){await page.getByRole('button',{name:'Свойства',exact:true}).click();const card=page.getByRole('dialog');await card.getByLabel('Отображаемое имя',{exact:true}).waitFor();assert.equal(await card.evaluate(e=>e.scrollWidth>e.clientWidth),false,'mobile user card must fit');await card.getByRole('button',{name:'Закрыть окно',exact:true}).click();}}
assert.deepEqual(errors,[]);console.log('PASS compact menus preserve handlers, submitter values and CSRF; keyboard Escape, dynamic updates and mobile');}finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1;});
